% WAIT FOR DATA, REST NO OK.
%%
% scat in three file but one instrument
P1=timerange('2016-01-01','2023-01-01');
P2=timerange('2023-01-01','2024-09-14');
P3=timerange('2025-01-01','2026-01-01');

SYO_rd.BsG_S=NaN(size(SYO_rd.Bs5500_S));
