T_SYO_bscat_BP=make_table_breakpoints_def(break_SYO_bscat_BP);
%%
%AE131 could be homogenised with CLAP:
% common period= 1.8.1997 - 9.12.2001
Pt=timerange('2019-01-01','2020-01-01');
ratio_med_h=nanmedian(SYO_rd.BaG0_A(Pt)./SYO_rd.Ba30_A(Pt)); %0.99
ratio_STN_h=nanstd(SYO_rd.BaG0_A(Pt)./SYO_rd.Ba30_A(Pt)); % 0.3175 
ratio_mean_h=nanmean(SYO_rd.BaG0_A(Pt)./SYO_rd.Ba30_A(Pt)); %1.0061
ratio_mean=nanmean(SYO_rd.BaG0_A(Pt))/nanmean(SYO_rd.Ba30_A(Pt)); %0.6480
ratio_median=nanmedian(SYO_rd.BaG0_A(Pt))/nanmedian(SYO_rd.Ba30_A(Pt)); %0.4255
figure;
plot(SYO_rd.BaG0_A(Pt),SYO_rd.Ba30_A(Pt),'.');

% fit between both data: slope 0.9575x+0.1082
fit_test=robustfit(SYO_rd.BaG0_A(Pt),SYO_rd.Ba30_A(Pt)); % y coor=0.0258, slope=0.9849, 1/slope=0.9251
